        calls: ["validation_context", { n: "StableIdentifierPolicy", d: T("Política común de identificadores estables de elemento.", "Shared stable element identifier policy.") }],
        usedBy: ["validation_model", "validation_model_checker", "validation_compiler", "validation_rule_editor"],
