        rat: { k: "observable", t: T("Rol arquitectónico observable en la implementación: el motor distingue ámbitos globales de por-candidato (ValidationEngine.isGlobal) y el comprobador valida cada tipo.", "Observable architectural role in the implementation: the engine distinguishes global from per-candidate scopes (ValidationEngine.isGlobal) and the checker validates each kind."), src: [] },
