        prod: T("ValidationCompilationResult: plan ejecutable, diagnósticos de compilación y bandera cacheHit.", "ValidationCompilationResult: executable plan, compilation diagnostics and cacheHit flag."),
        calls: ["validation_model_checker", "validation_plan_cache"],
