        excerpts: [
          { path: J + "runtime/ValidationCompiler.java", from: 45, to: 47,
            code: "        String fingerprint = fingerprint(metamodel, expressions, actions, validations, versions);\n        var cached = cache.find(fingerprint);\n        if(cached.isPresent()) return new ValidationCompilationResult(cached.get(), cached.get().diagnostics(), true);",
            what: T("Entrada de la caché de planes: se calcula la huella SHA-256 de metamodelo, expresiones, acciones, validaciones y versiones (ETag) y, si ya existe un plan con esa huella, se devuelve sin recompilar.", "Plan cache entry point: the SHA-256 fingerprint of metamodel, expressions, actions, validations and versions (ETags) is computed and, if a plan with that fingerprint exists, it is returned without recompiling."),
            why: T("Validar al abrir, cambiar y guardar ejecutaría el compilador muchas veces; la huella evita recompilar mientras ninguna fuente cambie y la invalida sola cuando cambia el contenido (no solo el ETag).", "Validating on open, change and save would run the compiler many times; the fingerprint avoids recompiling while no source changes and invalidates itself when content changes (not only the ETag)."),
            role: T("Primera instrucción de compile: decide entre reutilizar el plan y compilar de nuevo.", "First statement of compile: decides between reusing the plan and compiling anew."),
            in: T("Las cinco fuentes y sus versiones.", "The five sources and their versions."), out: T("Un resultado con cacheHit=true, o continúa la compilación.", "A result with cacheHit=true, or compilation continues."),
            behavior: T("La huella incluye el toString de las fuentes además de las versiones; por eso un cambio de contenido sin ETag nuevo también produce otro plan (test sourceContentAlsoInvalidatesCacheWhenCallerHasNoNewEtagYet).", "The fingerprint includes the sources' toString besides the versions; hence a content change without a new ETag also yields another plan (test sourceContentAlsoInvalidatesCacheWhenCallerHasNoNewEtagYet)."),
            related: ["validation_plan_cache"] },
          { path: J + "runtime/ValidationCompiler.java", from: 59, to: 74,
            code: "        for(ValidationRule rule : ordered) {\n            if(!rule.enabled()) {\n                diagnostics.add(info(\"RULE_DISABLED\", rule.id(), \"Disabled rule was omitted from the executable plan\"));\n                continue;\n            }\n            ValidationRuleCheckResult ruleCheck = checkByRule.get(rule.id());\n            if(ruleCheck != null) ruleCheck.diagnostics().forEach(item -> diagnostics.add(convert(item)));\n            if(ruleCheck != null && ruleCheck.hasErrors()) continue;\n            if(rule.executionMode() == ValidationExecutionMode.EXTERNAL || rule.conversionStatus() == ConversionStatus.EXTERNAL || rule.conversionStatus() == ConversionStatus.UNSUPPORTED) {\n                diagnostics.add(warning(\"RULE_NOT_EXECUTABLE_IN_CANONICAL_RUNTIME\", rule.id(), \"External or unsupported rule remains preserved but was omitted from the canonical plan\"));\n                continue;\n            }\n            if(rule.authoritativeRepresentation() != AuthoritativeRepresentation.CANONICAL && rule.conversionStatus() != ConversionStatus.FULL) {\n                diagnostics.add(warning(\"PARTIAL_EXTERNAL_RULE_OMITTED\", rule.id(), \"Partially converted external rule was not selected as executable canonical behavior\"));\n                continue;\n            }",
            what: T("Lógica de exclusión: cada regla se descarta del plan por una de cuatro razones (desactivada, con errores de diseño, externa/no soportada, importada con conversión parcial) y cada descarte deja un diagnóstico.", "Exclusion logic: each rule is dropped from the plan for one of four reasons (disabled, design errors, external/unsupported, imported with partial conversion) and each drop leaves a diagnostic."),
            why: T("Garantiza que el motor solo ejecuta lo canónico y comprobado, y que lo conservado pero no ejecutable se comunica (RULE_DISABLED, RULE_NOT_EXECUTABLE_IN_CANONICAL_RUNTIME, PARTIAL_EXTERNAL_RULE_OMITTED) en vez de desaparecer en silencio.", "Guarantees the engine only runs canonical, checked rules, and that rules preserved but not executable are reported (RULE_DISABLED, RULE_NOT_EXECUTABLE_IN_CANONICAL_RUNTIME, PARTIAL_EXTERNAL_RULE_OMITTED) instead of vanishing silently."),
            role: T("Cuerpo del bucle principal de compile; define qué reglas entran en el plan que ejecutará ValidationEngine.", "Body of compile's main loop; defines which rules enter the plan ValidationEngine will run."),
            in: T("Reglas ordenadas por grupo, resultado del comprobador por regla.", "Rules ordered by group, per-rule checker result."), out: T("Diagnósticos de compilación y, para las reglas que superan los cuatro filtros, una CompiledValidationRule.", "Compilation diagnostics and, for rules passing the four filters, a CompiledValidationRule."),
            behavior: T("Un error del comprobador sobre una regla la excluye pero no invalida el plan; la regla rota reaparece luego como diagnóstico BROKEN_RULE en el informe (ValidationEngine.validate).", "A checker error on a rule excludes it but does not invalidate the plan; the broken rule later resurfaces as a BROKEN_RULE diagnostic in the report (ValidationEngine.validate)."),
            related: ["validation_model_checker", "validation_engine", "safe_external_translator"] }
        ],
