        rel: T("Es la implementación de «Ejecutar una validación»: selección por modo, candidatos por ámbito, evaluación de condición y emisión de diagnósticos.", "It implements \"Run a validation\": selection by mode, candidates by scope, condition evaluation and diagnostic emission."),
        rat: { k: "proven", t: T("Javadoc «Ejecuta planes compilados sobre CanonicalModelDocument sin depender de EMF o de la UI»; ValidationEngineTests fija selección por modo, id estable, separación entre violación y error de ejecución, y regla rota sin detener a las sanas.", "Javadoc \"runs compiled plans over CanonicalModelDocument without depending on EMF or the UI\"; ValidationEngineTests pins mode selection, stable id, separation of violation and execution error, and a broken rule not stopping healthy ones."), src: [{ path: J + "runtime/ValidationEngine.java", line: 36 }, { path: TJ + "runtime/ValidationEngineTests.java", line: 103 }] },
        src: [{ path: J + "runtime/ValidationEngine.java", line: 54, end_line: 135, label: "validate" }, { path: J + "runtime/ValidationEngine.java", line: 137, end_line: 171, label: "evaluate" }, { path: J + "runtime/ValidationEngine.java", line: 173, end_line: 213, label: "selectRuleIds + eligibleForMode" }, { path: J + "runtime/ValidationEngine.java", line: 215, end_line: 240, label: "candidates" }, { path: J + "runtime/ValidationEngine.java", line: 269, end_line: 288, label: "message + stableDiagnosticId" }],
