        usedBy: [{ n: "Shell del diseñador de metamodelos", d: T("Lo monta con el metamodelo activo.", "Mounts it with the active metamodel.") }],
        fx: T("Llamadas HTTP de creación/reemplazo por documento; estado React local.", "HTTP create/replace calls per document; local React state."),
        rel: T("Es el lado cliente de «Definir una regla»: aquí se bloquea el guardado con errores de diseño (el servidor no lo hace).", "It is the client side of \"Define a rule\": saving is blocked here on design errors (the server does not)."),
